"use strict";document.body.addEventListener("htmx:after-swap",function(evt){let el=evt.target;if(el.id!="rc-swap")return;el.childNodes.forEach(function(child){let targets;let selector=child.getAttribute("rc-swap");if(!selector){if(!child.id){console.error("Swap-Element must have either rc-swap attribute or an id!",child);return}
targets=document.querySelectorAll("#"+child.id)}else{targets=document.querySelectorAll("[rc-swap='"+selector+"']")}
targets.forEach((oldEl)=>{if(oldEl===child)return;oldEl.replaceWith(child.cloneNode(!0))})});el.remove()})